//! Rust port of pinned CCCL `thrust/examples/constant_iterator.cu`.

use cuda_core::{CudaContext, DeviceBuffer};
use rccl_thrust::{memory::CudaMemoryResource, range::RepeatN};
use std::error::Error;

rccl_thrust::thrust_kernels!();

fn main() -> Result<(), Box<dyn Error>> {
    let context = CudaContext::new(0)?;
    let stream = context.default_stream();
    let allocator = CudaMemoryResource::new(context.clone());
    // SAFETY: this executable owns the sole artifact generated by
    // `thrust_kernels!`; cuda-oxide requires provenance to be stated at bind.
    let module = unsafe { __rccl_thrust_kernels::load(&context)? };
    let exec = rccl_thrust::cuda::par(&stream, &allocator, &module)?;

    let mut data = DeviceBuffer::from_host(&stream, &[3_i32, 7, 2, 5])?;
    let repeated = RepeatN::new(10_i32, data.len());
    rccl_thrust::transform!(&exec, &mut data, repeated, |left, right| left + right)?;

    assert_eq!(data.to_host_vec(&stream)?, [13, 17, 12, 15]);
    println!("pinned CCCL constant_iterator example: PASS");
    Ok(())
}
